pub fn read_once(alias:&str)->Outcome{
 let mut bytes=[0u8;State::MAX_WIRE_BYTES];
 #[cfg(any(feature="kinetic_mycobot",feature="kinetic_mypalletizer",feature="melodic_mecharm",feature="melodic_myarm",feature="melodic_mybuddy",feature="melodic_mycobot320",feature="melodic_mycobot",feature="melodic_mypalletizer",feature="melodic_ultraarm",feature="noetic_mecharm",feature="noetic_myarm",feature="noetic_mybuddy",feature="noetic_mycobot320",feature="noetic_mycobot",feature="noetic_pro450",feature="noetic_mypalletizer",feature="noetic_ultraarm"))] let backend=Backend::Ros1;
 #[cfg(any(feature="foxy_mecharm",feature="foxy_mycobot",feature="foxy_pro450",feature="foxy_mypalletizer",feature="galactic_mecharm",feature="galactic_mycobot",feature="galactic_pro450",feature="galactic_mypalletizer",feature="humble_mecharm",feature="humble_mycobot",feature="humble_pro450",feature="humble_mypalletizer",feature="humble_ultraarm"))] let backend=Backend::Ros2;
 let mut cap=match Capability::open(backend,alias){Ok(v)=>v,Err(e)=>return Outcome{primary:e.code,cleanup:0,value:None}};
 let result=cap.subscribe().and_then(|()|cap.poll(&mut bytes)).and_then(|n|State::decode(&bytes[..n]));
 let cleanup=cap.close().err().map_or(0,|e|e.code);
 match result{Ok(value)=>Outcome{primary:0,cleanup,value:Some(value)},Err(e)=>Outcome{primary:e.code,cleanup,value:None}}
}
